<script setup lang="ts">
import {ref,watch,nextTick,computed} from 'vue';import NetworkView from './NetworkView.vue';import FaultPicker from './FaultPicker.vue';import {apiError} from './apiError';
const network=defineModel<any>({required:true});const failures=defineModel<number[]>('failures',{required:true});const props=defineProps<{disabled:boolean;placement:{wind_node:number;pv_node:number};focus?:string;managed?:boolean}>();
const draft=ref<any>(null);const message=ref('');const valid=ref(false);const initial=ref('');
const selectedObject=ref<{type:string;id:number}|null>(null);
const selectedData=computed(()=>!draft.value||!selectedObject.value?null:(selectedObject.value.type==='节点'?draft.value.nodes.find((n:any)=>n.node===selectedObject.value!.id):draft.value.lines.find((l:any)=>l.line===selectedObject.value!.id)));
const propertiesOpen=ref(false);
const inspectorOpen=ref(false);
function openEditor(){draft.value=network.value?JSON.parse(JSON.stringify(network.value)):null;propertiesOpen.value=true}
function cancelEditor(){draft.value=network.value?JSON.parse(JSON.stringify(network.value)):null;propertiesOpen.value=false;inspectorOpen.value=false}
function openProperties(){if(selectedObject.value)inspectorOpen.value=true;else message.value='请先在拓扑图选中节点或线路，再打开属性。'}
const importInput=ref<HTMLInputElement>();function openImport(){openEditor();importInput.value?.click()}
defineExpose({openEditor,openProperties,openImport});
const editorTab=ref('拓扑与故障');
const showNodes=computed(()=>editorTab.value==='节点编辑');
const showLines=computed(()=>editorTab.value==='线路编辑');
watch(network,v=>{draft.value=v?JSON.parse(JSON.stringify(v)):null;initial.value=JSON.stringify(draft.value);valid.value=!!v},{immediate:true,deep:true});
watch(draft,()=>{valid.value=JSON.stringify(draft.value)===initial.value&&!!network.value},{deep:true});
async function example(){try{const r=await fetch('/api/network/case33');if(!r.ok)throw Error('示例读取失败');draft.value={name:'IEEE33示例电网',base_voltage_kv:12.66,...await r.json()};message.value='已载入示例草稿，校验并应用后生效。'}catch(e){message.value=String(e)}}
function empty(){draft.value={name:'新建电网（待录入）',source:'人工录入；需核实线路参数',base_voltage_kv:10,nodes:[{node:1,name:'上级电源',type:3,pd_kw:0,qd_kvar:0,vm_init_pu:1},{node:2,name:'负荷节点',type:1,pd_kw:1,qd_kvar:0,vm_init_pu:1}],lines:[{line:1,name:'待核实线路',from_node:1,to_node:2,r_ohm:0,x_ohm:0,status:1}]};message.value='新建的是录入模板，请按图纸填写端点、负荷和阻抗后应用。'}
function addNode(){const id=Math.max(...draft.value.nodes.map((n:any)=>n.node))+1;draft.value.nodes.push({node:id,name:'节点'+id,type:1,pd_kw:0,qd_kvar:0,vm_init_pu:1})}
function addLine(){draft.value.lines.push({line:Math.max(0,...draft.value.lines.map((l:any)=>l.line))+1,name:'新线路',from_node:1,to_node:draft.value.nodes.at(-1).node,r_ohm:0,x_ohm:0,status:1})}
async function apply(){try{const r=await fetch('/api/network/validate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(draft.value)});const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));network.value=d;props.placement.wind_node=d.nodes.some((n:any)=>n.node===props.placement.wind_node)?props.placement.wind_node:1;props.placement.pv_node=d.nodes.some((n:any)=>n.node===props.placement.pv_node)?props.placement.pv_node:1;failures.value=failures.value.filter(id=>d.lines.some((l:any)=>l.line===id&&l.status));await nextTick();message.value='网络校验通过并已应用，请保存工程。';valid.value=true;inspectorOpen.value=false;propertiesOpen.value=false}catch(e){message.value=String(e)}}
function exportJson(){const u=URL.createObjectURL(new Blob([JSON.stringify(draft.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='network.json';a.click();URL.revokeObjectURL(u)}
async function upload(e:Event){const input=e.target as HTMLInputElement;try{const f=input.files?.[0];if(f){if(f.size>500000)throw Error('文件过大');const d=JSON.parse(await f.text());if(!Array.isArray(d.nodes)||!Array.isArray(d.lines))throw Error('需要nodes和lines数组');draft.value=d;message.value='JSON已载入草稿；应用新拓扑后将解除旧场景及线路故障，请校验后明确应用。'}}catch(e){message.value=String(e)}finally{input.value=''}}
</script>
<template><article :class="{'network-object-layout':inspectorOpen&&!propertiesOpen}"><button v-if="!managed" @click="propertiesOpen?cancelEditor():openEditor()">{{propertiesOpen?'关闭编辑器':'网络编辑 / 故障设置'}}</button><div v-if="!managed||message" class="actions"><button v-if="!managed" :disabled="!selectedObject" @click="openProperties">对象属性</button><span v-if="message">{{message}}</span></div><NetworkView v-if="draft&&!propertiesOpen" :network="draft" :placement="placement" :failed-lines="failures" :selected-node="selectedObject?.type==='节点'?selectedObject.id:undefined" :selected-line="selectedObject?.type==='线路'?selectedObject.id:undefined" @inspect-node="id=>{selectedObject={type:'节点',id};inspectorOpen=true}" @inspect-line="id=>{selectedObject={type:'线路',id};inspectorOpen=true}" @select-node="id=>{selectedObject={type:'节点',id};inspectorOpen=true}" @select-line="id=>{selectedObject={type:'线路',id};inspectorOpen=true}"/><div v-if="selectedData&&inspectorOpen&&!propertiesOpen" class="object-inspector"><button @click="inspectorOpen=false">× 关闭属性</button><h3>{{selectedObject?.type}} {{selectedObject?.id}} 属性</h3><label>名称<input v-model="selectedData.name" :disabled="true"></label><template v-if="selectedObject?.type==='节点'"><label>有功负荷 / kW<input type="number" v-model.number="selectedData.pd_kw" :disabled="true"></label><label>无功负荷 / kvar<input type="number" v-model.number="selectedData.qd_kvar" :disabled="true"></label></template><template v-else><label>电阻 / Ω<input type="number" step="any" v-model.number="selectedData.r_ohm" :disabled="true"></label><label>电抗 / Ω<input type="number" step="any" v-model.number="selectedData.x_ohm" :disabled="true"></label></template><p>浏览模式只读；进入编辑模式后修改并校验应用。</p><button @click="propertiesOpen=true;editorTab=selectedObject?.type==='节点'?'节点编辑':'线路编辑'">编辑此对象</button></div><p v-if="!draft&&!propertiesOpen">尚无网络。打开编辑器导入拓扑或选择示例。</p><div v-show="propertiesOpen"><button @click="cancelEditor">取消编辑，返回拓扑</button><div class="editor-tabs" role="tablist" aria-label="电网拓扑编辑"><button v-for="name in ['拓扑与故障','节点编辑','线路编辑']" :key="name" role="tab" :aria-selected="editorTab===name" :class="{current:editorTab===name}" @click="editorTab=name">{{name}}</button></div><h3>{{focus==='电网节点'?'电网节点编辑':focus==='电网线路'?'电网线路编辑':'电网拓扑与故障点编辑'}}</h3><p v-if="focus==='电网节点'">当前页面显示节点编辑表，可添加或删除节点并修改节点编号、名称、有功负荷和无功负荷。修改后点击“校验并应用网络”。</p><p v-else-if="focus==='电网线路'">当前页面显示线路编辑表，可添加或删除线路并修改端点、阻抗、容量和投运状态。修改后点击“校验并应用网络”。</p><p v-else>修改草稿后点击“校验并应用”，再保存工程。支持最多100节点的连通辐射网；故障断线请在已应用网络上设置。阻抗单位Ω，负荷单位kW/kvar。逐设备调度使用每线路kVA容量；旧IEEE33入口仍使用统一支路限额。</p><div class="actions"><button @click="example" :disabled="disabled">载入IEEE33示例草稿</button><button @click="empty" :disabled="disabled">新建网络草稿</button><label class="button">导入网络JSON<input ref="importInput" type="file" accept=".json" hidden @change="upload" :disabled="disabled"></label></div><p class="notice" v-if="message">{{message}}</p><template v-if="draft"><label>网络名称<input v-model="draft.name" :disabled="disabled"></label><label>基准电压 / kV<input type="number" v-model.number="draft.base_voltage_kv" :disabled="disabled"></label><label>数据来源<input v-model="draft.source" :disabled="disabled"></label><details v-if="showNodes" open><summary>节点编辑</summary><div class="scroll"><table><tr><th>编号</th><th>名称</th><th>有功负荷</th><th>无功负荷</th><th></th></tr><tr v-for="(n,i) in draft.nodes" :key="i"><td><input type="number" v-model.number="n.node" :disabled="disabled"></td><td><input v-model="n.name" :disabled="disabled"></td><td><input type="number" v-model.number="n.pd_kw" :disabled="disabled"></td><td><input type="number" v-model.number="n.qd_kvar" :disabled="disabled"></td><td><button @click="draft.nodes.splice(i,1)" :disabled="disabled||n.node===1">删除</button></td></tr></table></div><button @click="addNode" :disabled="disabled">添加节点</button></details><details v-if="showLines" open><summary>线路编辑</summary><div class="scroll"><table><tr><th>编号</th><th>线路名称</th><th>首节点</th><th>末节点</th><th>电阻 / Ω</th><th>电抗 / Ω</th><th>容量 / kVA（可空）</th><th>投运</th><th></th></tr><tr v-for="(l,i) in draft.lines" :key="i"><td><input type="number" v-model.number="l.line" :disabled="disabled"></td><td><input v-model="l.name" :disabled="disabled"></td><td><input type="number" v-model.number="l.from_node" :disabled="disabled"></td><td><input type="number" v-model.number="l.to_node" :disabled="disabled"></td><td><input type="number" step="any" v-model.number="l.r_ohm" :disabled="disabled"></td><td><input type="number" step="any" v-model.number="l.x_ohm" :disabled="disabled"></td><td><input type="number" min="0" :value="l.capacity_kva" @input="l.capacity_kva=($event.target as HTMLInputElement).value===''?null:Number(($event.target as HTMLInputElement).value)" :disabled="disabled"></td><td><select v-model.number="l.status" :disabled="disabled"><option :value="1">投运</option><option :value="0">备用</option></select></td><td><button @click="draft.lines.splice(i,1)" :disabled="disabled">删除</button></td></tr></table></div><button @click="addLine" :disabled="disabled">添加线路</button></details><div class="actions"><button @click="apply" :disabled="disabled">校验并应用网络</button><button @click="exportJson">导出草稿JSON</button><span>{{valid?'已应用':'草稿修改尚未应用'}}</span></div></template><template v-if="network&&editorTab==='拓扑与故障'"><h3>已应用网络 · 故障点设置</h3><p>点击图中线路或勾选故障点。红色虚线表示故障；启用运行阶段时，请在各阶段单独设置故障与恢复。</p><NetworkView :network="network" :placement="placement" :failed-lines="failures" :editable="!disabled" @toggle-line="id=>failures=failures.includes(id)?failures.filter(n=>n!==id):[...failures,id]"/><FaultPicker v-model="failures" :lines="network.lines" :disabled="disabled"/></template></div></article></template>
<style scoped>.editor-tabs{display:flex;gap:8px;margin-bottom:20px}.editor-tabs .current{background:#087b7b;color:white}details{margin:18px 0}summary{cursor:pointer}input{width:100px;padding:7px;border:1px solid #cbdde0}label{display:flex;gap:12px;margin:12px 0;align-items:center}label input{width:360px}td:nth-child(2) input{width:180px}.scroll{max-height:420px;overflow:auto;margin:12px 0}.object-inspector{background:#f9fafc;border-left:1px solid #dce3ea;padding:12px;overflow:auto;min-width:0}.network-object-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:8px}.network-object-layout>.topology{grid-column:1}.network-object-layout>.object-inspector{grid-column:2;grid-row:1/5}.network-object-layout>div:not(.topology):not(.object-inspector),.network-object-layout>p{grid-column:1/-1}.object-inspector label{display:block;margin:20px 0;font-size:13px}.object-inspector input{display:block;width:95%;margin-top:8px;padding:8px}.object-inspector p{font-size:12px;color:#6c7d91}</style>

